steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      query {
        teams(name: \"Web Platform\") {
          nodes {
            id
            name
            key
          }
        }
        users(orderBy: name, query: \"Priya Nair\") {
          nodes {
            id
            name
            displayName
          }
        }
      }
    "
  }'
